import test from'node:test';import assert from'node:assert/strict';import{readFile,readdir}from'node:fs/promises';
const routes=['index','adopt','foster','volunteer','donate','tnr','about','found-a-cat','contact'];
test('required routes and unique metadata exist',async()=>{const titles=new Set;for(const r of routes){const h=await readFile(`${r}.html`,'utf8');assert.match(h,/<meta name="description"/);assert.match(h,/rel="canonical"/);assert.match(h,/application\/ld\+json/);const t=h.match(/<title>(.*?)<\/title>/)?.[1];assert.ok(t);assert.ok(!titles.has(t));titles.add(t)}});
test('footer contains nonprofit disclosure and mobile actions',async()=>{const js=await readFile('src/main.js','utf8');assert.match(js,/501\(c\)\(3\)/);assert.match(js,/EIN XX-XXXXXXX/);for(const x of['Donate','Adopt','Call'])assert.match(js,new RegExp(x))});
test('forms use honeypot and fixed recipient env',async()=>{for(const r of['contact','tnr'])assert.match(await readFile(`${r}.html`,'utf8'),/name="website"/);const f=await readFile('api/_forms.js','utf8');assert.match(f,/CONTACT_RECIPIENT_EMAIL/);assert.doesNotMatch(f,/req\.body\.to/)});
test('ShelterLuv has cache and fallback',async()=>{assert.match(await readFile('api/shelterluv.js','utf8'),/s-maxage=600/);assert.match(await readFile('src/main.js','utf8'),/cat list is taking a catnap/)});
test('CMS image fields require alt text',async()=>{const y=await readFile('admin/config.yml','utf8');for(const x of['photo_alt','cover_alt'])assert.match(y,new RegExp(x));assert.match(y,/editorial_workflow/)});
test('all authored img elements have alt',async()=>{for(const file of await readdir('.'))if(file.endsWith('.html')){const h=await readFile(file,'utf8');for(const tag of h.match(/<img\b[^>]*>/g)||[])assert.match(tag,/\balt=/)}});
